import numpy as np
from . import REM_BaseTypes



class REM_RobotStateInfo:
    packetType = 0            # integer [0, 255]             Byte indicating the type of packet
    toRobotId = 0             # integer [0, 15]              Id of the receiving robot
    toColor = 0               # integer [0, 1]               Color of the receiving robot / basestation. Yellow = 0, Blue = 1
    toBC = 0                  # integer [0, 1]               Bit indicating this packet has to be broadcasted to all robots
    toBS = 0                  # integer [0, 1]               Bit indicating this packet is meant for the basestation
    toPC = 0                  # integer [0, 1]               Bit indicating this packet is meant for the PC
    fromRobotId = 0           # integer [0, 15]              Id of the transmitting robot
    fromColor = 0             # integer [0, 1]               Color of the transmitting robot / basestation. Yellow = 0, Blue = 1
    reserved = 0              # integer [0, 1]               reserved
    fromBS = 0                # integer [0, 1]               Bit indicating this packet is coming from the basestation
    fromPC = 0                # integer [0, 1]               Bit indicating this packet is coming from the PC
    remVersion = 0            # integer [0, 15]              Version of roboteam_embedded_messages
    messageId = 0             # integer [0, 15]              messageId. Can be used for aligning packets
    timestamp = 0             # integer [0, 281474976710655] Unix Timestamp in milliseconds
    payloadSize = 0           # integer [0, 255]             Size of the payload. At most 255 bytes including the generic_packet_header. Keep the 127 byte SX1280 limit in mind
    xsensAcc1 = 0             # float   [-100.000, 100.000]  xsensAcc1
    xsensAcc2 = 0             # float   [-100.000, 100.000]  xsensAcc2
    xsensYaw = 0              # float   [-50000.000, 50000.000] xsensYaw
    rateOfTurn = 0            # float   [-20.000, 20.000]    rateOfTurn
    wheelSpeed1 = 0           # float   [-1000.000, 1000.000] wheelSpeed1
    wheelSpeed2 = 0           # float   [-1000.000, 1000.000] wheelSpeed2
    wheelSpeed3 = 0           # float   [-1000.000, 1000.000] wheelSpeed3
    wheelSpeed4 = 0           # float   [-1000.000, 1000.000] wheelSpeed4
    dribbleSpeed = 0          # float   [0.000, 5000.000]    dribblerSpeed
    filteredDribbleSpeed = 0  # float   [0.000, 5000.000]    filtered dribblerSpeed
    dribblespeedBeforeGotBall = 0 # float   [0.000, 5000.000]    dribblerSpeed at at the time dribbler thinks it got the ball
    bodyXIntegral = 0         # float   [-200.000, 200.000]  Integral value from the PID for body_x
    bodyYIntegral = 0         # float   [-200.000, 200.000]  Integral value from the PID for body_y
    bodyWIntegral = 0         # float   [-200.000, 200.000]  Integral value from the PID for body_w
    bodyYawIntegral = 0       # float   [-10.000, 10.000]    Integral value from the PID for body_Yaw
    wheel1Integral = 0        # float   [-1000.000, 1000.000] Integral value from the PID for Wheel_1
    wheel2Integral = 0        # float   [-1000.000, 1000.000] Integral value from the PID for Wheel_2
    wheel3Integral = 0        # float   [-1000.000, 1000.000] Integral value from the PID for Wheel_3
    wheel4Integral = 0        # float   [-1000.000, 1000.000] Integral value from the PID for Wheel_4
    wheelSpeedRef1 = 0        # float   [-1000.000, 1000.000] Reference speed of Wheel_1
    wheelSpeedRef2 = 0        # float   [-1000.000, 1000.000] Reference speed of Wheel_2
    wheelSpeedRef3 = 0        # float   [-1000.000, 1000.000] Reference speed of Wheel_3
    wheelSpeedRef4 = 0        # float   [-1000.000, 1000.000] Reference speed of Wheel_4
    wheelController_1 = 0     # float   [-1.000, 1.000]      Wheel_1 controller output
    wheelController_2 = 0     # float   [-1.000, 1.000]      Wheel_2 controller output
    wheelController_3 = 0     # float   [-1.000, 1.000]      Wheel_3 controller output
    wheelController_4 = 0     # float   [-1.000, 1.000]      Wheel_4 controller output
    bodyController_u = 0      # float   [-100.000, 100.000]  Body u controller output
    bodyController_v = 0      # float   [-100.000, 100.000]  Body v controller output
    bodyController_w = 0      # float   [-100.000, 100.000]  Body w controller output
